import{_ as a,c as t,o as s,a5 as n}from"./chunks/framework.DYgWcJ6Z.js";const d=JSON.parse('{"title":"Programming Languages","description":"","frontmatter":{},"headers":[],"relativePath":"contributing/programming_languages.md","filePath":"contributing/programming_languages.md","lastUpdated":1722238150000}'),r={name:"contributing/programming_languages.md"};function o(i,e,g,l,p,h){return s(),t("div",null,e[0]||(e[0]=[n('<h1 id="programming-languages" tabindex="-1">Programming Languages <a class="header-anchor" href="#programming-languages" aria-label="Permalink to &quot;Programming Languages&quot;">​</a></h1><p>There are several programming languages that we used in this project, we know that it might be hard to understand this decision, but we have our reasons, and we will explain them in this document, and define the rules that we follow in selecting the programming languages.</p><h2 id="selected-programming-languages" tabindex="-1">Selected Programming Languages <a class="header-anchor" href="#selected-programming-languages" aria-label="Permalink to &quot;Selected Programming Languages&quot;">​</a></h2><p>We selected the following programming languages to be used in this project:</p><ul><li>C/C++</li><li>Rust</li><li>TypeScript</li></ul><p>We use C/C++ for the main part of the project, including the main components such as the renderer, media, content manager and other services, the reason behind this is that C/C++ is most convenient for integrating with the other applications and 3d engines.</p><p>And in client-side, we use C/C++ to bootstrap the Node.js as the script thread, and expose the Web APIs to the JavaScript via the Node.js C++ Addons, the reason is also the Node.js and v8 has used C++ as its API language.</p><p>Rust has its usecases in the JSAR project. In Rust ecosystem, Mozila&#39;s <a href="https://github.com/servo/servo" target="_blank" rel="noreferrer">servo</a> project has achieved a lot of crates that can be used in building a Web browser especially the CSS parser and layout engine, these crates are the main reason why we include Rust to build JSAR.</p><p>As for TypeScript, it has been adopted as the default scripting language for Deno, Bun and Node.js, and there is still a project: AssemblyScript that compiles TypeScript-like code to WebAssembly for speed and performance, so we decided to use TypeScript as the scripting language for the project.</p><h2 id="language-rules" tabindex="-1">Language Rules <a class="header-anchor" href="#language-rules" aria-label="Permalink to &quot;Language Rules&quot;">​</a></h2><p>This section will define some rules that we follow in selecting the programming language when we need to add a new feature or component to the project.</p><p><strong>The less scripting language, the better of the performance</strong></p><p>We prefer to use the less scripting language as possible, because the scripting language (including WebAssembly) has a performance overhead at bootstrap and runtime, so we will keep the scripting language as less as possible.</p><p><strong>TypeScript should only call native from the C/C++</strong></p><p>Both the Rust and C/C++ languages could expose the JavaScript APIs via N-API, to make the architecture more consistent, we will only allow TypeScript to call the native APIs from the C/C++, it means that we can&#39;t use N-API with Rust.</p><p><strong>Rust should be restricted to add global states</strong></p><p>Rust is the programming language that is designed to be safe and concurrent, using Rust to add global states will make the project more complex and hard to maintain, thus we need to restrict the Rust not to add global states except for resources.</p>',17)]))}const u=a(r,[["render",o]]);export{d as __pageData,u as default};
